/** Local-date helpers. Dates are represented as 'YYYY-MM-DD' strings. */

export function toDateStr(d: Date): string {
  const y = d.getFullYear()
  const m = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  return `${y}-${m}-${day}`
}

export function todayStr(): string {
  return toDateStr(new Date())
}

/** Parse 'YYYY-MM-DD' as a local date (at noon to avoid DST edge cases). */
export function parseDateStr(s: string): Date {
  const [y, m, d] = s.split('-').map(Number)
  return new Date(y, m - 1, d, 12)
}

export function addDays(dateStr: string, n: number): string {
  const d = parseDateStr(dateStr)
  d.setDate(d.getDate() + n)
  return toDateStr(d)
}

export function diffDays(a: string, b: string): number {
  // b - a in whole days
  const ms = parseDateStr(b).getTime() - parseDateStr(a).getTime()
  return Math.round(ms / 86400000)
}

export function lastNDays(n: number, end: string = todayStr()): string[] {
  const out: string[] = []
  for (let i = n - 1; i >= 0; i--) out.push(addDays(end, -i))
  return out
}

export function formatLong(dateStr: string): string {
  return new Intl.DateTimeFormat('de-DE', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric'
  }).format(parseDateStr(dateStr))
}

export function formatShort(dateStr: string): string {
  return new Intl.DateTimeFormat('de-DE', {
    weekday: 'short',
    day: 'numeric',
    month: 'numeric'
  }).format(parseDateStr(dateStr))
}

export function weekdayShort(dateStr: string): string {
  return new Intl.DateTimeFormat('de-DE', { weekday: 'short' }).format(parseDateStr(dateStr))
}

export function dayMonthShort(dateStr: string): string {
  return new Intl.DateTimeFormat('de-DE', { day: 'numeric', month: 'short' }).format(parseDateStr(dateStr))
}

/** Streak calculation on a set of 'YYYY-MM-DD' completion dates. */

import { addDays, todayStr } from './dates'

/**
 * Current streak for one habit:
 * - if today is completed, count backwards from today
 * - else if yesterday is completed, count backwards from yesterday
 * - otherwise 0
 */
export function currentStreak(dates: Set<string>, today: string = todayStr()): number {
  let cursor: string
  if (dates.has(today)) {
    cursor = today
  } else {
    const yesterday = addDays(today, -1)
    if (dates.has(yesterday)) {
      cursor = yesterday
    } else {
      return 0
    }
  }
  let count = 0
  while (dates.has(cursor)) {
    count++
    cursor = addDays(cursor, -1)
  }
  return count
}

/** Longest run of consecutive completed days in the whole history. */
export function longestStreak(dates: Set<string>): number {
  if (dates.size === 0) return 0
  const sorted = [...dates].sort()
  let best = 1
  let run = 1
  let prev = sorted[0]
  for (let i = 1; i < sorted.length; i++) {
    const cur = sorted[i]
    if (addDays(prev, 1) === cur) {
      run++
      if (run > best) best = run
    } else if (prev !== cur) {
      run = 1
    }
    prev = cur
  }
  return best
}

/** Habit color palette. Light/dark variants kept WCAG-AA friendly. */

export type HabitColorKey =
  | 'clay'
  | 'forest'
  | 'teal'
  | 'slate'
  | 'ochre'
  | 'plum'
  | 'sage'

export interface HabitColor {
  key: HabitColorKey
  label: string
  light: string
  dark: string
}

export const HABIT_COLORS: HabitColor[] = [
  { key: 'clay', label: 'Terrakotta', light: '#B4542C', dark: '#E08E5F' },
  { key: 'forest', label: 'Waldgrün', light: '#3E6B4F', dark: '#8FBF9C' },
  { key: 'teal', label: 'Teal', light: '#2F6B6B', dark: '#7FC0BB' },
  { key: 'slate', label: 'Steingrau', light: '#3F5E7A', dark: '#8FA8C4' },
  { key: 'ochre', label: 'Ocker', light: '#8A6A1F', dark: '#D8B65C' },
  { key: 'plum', label: 'Pflaume', light: '#6E4A63', dark: '#C99BB8' },
  { key: 'sage', label: 'Salbei', light: '#4A6B3F', dark: '#A3C98F' }
]

export function habitColor(key: HabitColorKey, resolved: 'light' | 'dark'): string {
  const found = HABIT_COLORS.find((c) => c.key === key)
  if (!found) return HABIT_COLORS[0].light
  return resolved === 'dark' ? found.dark : found.light
}

export function habitColorLabel(key: HabitColorKey): string {
  return HABIT_COLORS.find((c) => c.key === key)?.label ?? key
}

export function habitColorLight(key: HabitColorKey): string {
  return habitColor(key, 'light')
}

export function habitColorDark(key: HabitColorKey): string {
  return habitColor(key, 'dark')
}

export function withAlpha(hex: string, alpha: number): string {
  const h = hex.replace('#', '')
  const r = parseInt(h.slice(0, 2), 16)
  const g = parseInt(h.slice(2, 4), 16)
  const b = parseInt(h.slice(4, 6), 16)
  return `rgba(${r}, ${g}, ${b}, ${alpha})`
}

/** Mood (Stimmung) definitions. */

export interface MoodDef {
  value: 1 | 2 | 3 | 4 | 5
  emoji: string
  label: string
}

export const MOODS: MoodDef[] = [
  { value: 1, emoji: '\u{1F61E}', label: 'Schwierig' },
  { value: 2, emoji: '\u{1F615}', label: 'Angespannt' },
  { value: 3, emoji: '\u{1F610}', label: 'Neutral' },
  { value: 4, emoji: '\u{1F60A}', label: 'Gute Laune' },
  { value: 5, emoji: '\u{1F604}', label: 'Topfit' }
]

export function moodDef(value: number): MoodDef | undefined {
  return MOODS.find((m) => m.value === value)
}

export function moodLabel(value: number | null | undefined): string {
  if (value == null) return 'Nicht gezeichnet'
  return moodDef(value)?.label ?? 'Nicht gezeichnet'
}

import { openDB, type DBSchema, type IDBPDatabase } from 'idb'
import type { Habit, Completion, MoodEntry, Settings } from '../types'

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

interface RhythmDB extends DBSchema {
  habits: {
    key: string
    value: Habit
  }
  completions: {
    key: number
    value: Completion
    indexes: {
      'by-date': string
      'by-habit': string
      'by-habit-date': [string, string]
    }
  }
  moods: {
    key: number
    value: MoodEntry
    indexes: {
      'by-date': string
    }
  }
  settings: {
    key: string
    value: Settings
  }
}

let dbPromise: Promise<IDBPDatabase<RhythmDB>> | null = null

function getDB(): Promise<IDBPDatabase<RhythmDB>> {
  if (!dbPromise) {
    dbPromise = openDB<RhythmDB>(DB_NAME, DB_VERSION, {
      upgrade(db) {
        const habits = db.createObjectStore('habits', { keyPath: 'id' })
        habits.createIndex('createdAt', 'createdAt')

        const completions = db.createObjectStore('completions', {
          keyPath: 'id',
          autoIncrement: true
        })
        completions.createIndex('by-date', 'date')
        completions.createIndex('by-habit', 'habitId')
        completions.createIndex('by-habit-date', ['habitId', 'date'], { unique: true })

        const moods = db.createObjectStore('moods', {
          keyPath: 'id',
          autoIncrement: true
        })
        moods.createIndex('by-date', 'date', { unique: true })

        db.createObjectStore('settings', { keyPath: 'id' })
      }
    })
  }
  return dbPromise
}

export async function getAllHabits(): Promise<Habit[]> {
  const db = await getDB()
  const habits = await db.getAll('habits')
  return habits.sort((a, b) => a.createdAt.localeCompare(b.createdAt))
}

export async function addHabit(habit: Habit): Promise<void> {
  const db = await getDB()
  await db.put('habits', habit)
}

export async function updateHabit(habit: Habit): Promise<void> {
  const db = await getDB()
  await db.put('habits', habit)
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB()
  const tx = db.transaction(['habits', 'completions'], 'readwrite')
  await tx.objectStore('habits').delete(id)
  const completions = await tx.objectStore('completions').index('by-habit').getAll(id)
  for (const c of completions) {
    await tx.objectStore('completions').delete(c.id!)
  }
  await tx.done
}

export async function toggleCompletion(habitId: string, date: string): Promise<boolean> {
  const db = await getDB()
  const existing = await db.getFromIndex('completions', 'by-habit-date', [habitId, date])
  if (existing) {
    await db.delete('completions', existing.id!)
    return false
  }
  await db.add('completions', { habitId, date })
  return true
}

export async function getAllCompletions(): Promise<Completion[]> {
  const db = await getDB()
  return db.getAll('completions')
}

export async function getCompletionsForHabit(habitId: string): Promise<string[]> {
  const db = await getDB()
  const rows = await db.getAllFromIndex('completions', 'by-habit', habitId)
  return rows.map((r) => r.date)
}

export async function getMoods(): Promise<MoodEntry[]> {
  const db = await getDB()
  return db.getAll('moods')
}

export async function getMood(date: string): Promise<MoodEntry | undefined> {
  const db = await getDB()
  const rows = await db.getAllFromIndex('moods', 'by-date', date)
  return rows[0]
}

export async function setMood(date: string, mood: 1 | 2 | 3 | 4 | 5, note?: string): Promise<void> {
  const db = await getDB()
  const existing = await db.getAllFromIndex('moods', 'by-date', date)
  const entry: MoodEntry = { date, mood, note: note?.trim() ? note.trim() : undefined }
  if (existing[0]) {
    entry.id = existing[0].id
    await db.put('moods', entry)
  } else {
    await db.add('moods', entry)
  }
}

export async function clearMood(date: string): Promise<void> {
  const db = await getDB()
  const existing = await db.getAllFromIndex('moods', 'by-date', date)
  if (existing[0]) await db.delete('moods', existing[0].id!)
}

export async function getSetting(id: string): Promise<Settings | undefined> {
  const db = await getDB()
  return db.get('settings', id)
}

export async function setSetting(settings: Settings): Promise<void> {
  const db = await getDB()
  await db.put('settings', settings)
}

import { useCallback, useEffect, useState } from 'react'

export type ThemeMode = 'system' | 'light' | 'dark'
export type ResolvedTheme = 'light' | 'dark'

const STORAGE_KEY = 'rhythm-theme'

function readStoredMode(): ThemeMode {
  try {
    const v = localStorage.getItem(STORAGE_KEY)
    if (v === 'light' || v === 'dark' || v === 'system') return v
  } catch {
    // ignore
  }
  return 'system'
}

function resolveTheme(mode: ThemeMode): ResolvedTheme {
  if (mode === 'light' || mode === 'dark') return mode
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

export function useTheme() {
  const [mode, setModeState] = useState<ThemeMode>(readStoredMode)
  const [resolved, setResolved] = useState<ResolvedTheme>(() => resolveTheme(readStoredMode()))

  useEffect(() => {
    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    const apply = () => {
      const r = resolveTheme(mode)
      setResolved(r)
      document.documentElement.classList.toggle('dark', r === 'dark')
    }
    apply()
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [mode])

  const setMode = useCallback((m: ThemeMode) => {
    setModeState(m)
    try {
      localStorage.setItem(STORAGE_KEY, m)
    } catch {
      // ignore
    }
  }, [])

  return { mode, resolved, setMode }
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  getAllHabits,
  getAllCompletions,
  getMoods
} from '../db'
import type { Habit, Completion, MoodEntry } from '../types'
import { currentStreak, longestStreak } from '../lib/streaks'
import { todayStr } from '../lib/dates'

export interface RhythmData {
  loading: boolean
  habits: Habit[]
  completions: Completion[]
  moods: Map<string, MoodEntry>
  reload: () => Promise<void>
}

export function useRhythmData(): RhythmData {
  const [loading, setLoading] = useState(true)
  const [habits, setHabits] = useState<Habit[]>([])
  const [completions, setCompletions] = useState<Completion[]>([])
  const [moods, setMoods] = useState<Map<string, MoodEntry>>(new Map())

  const reload = useCallback(async () => {
    const [h, c, m] = await Promise.all([getAllHabits(), getAllCompletions(), getMoods()])
    setHabits(h)
    setCompletions(c)
    setMoods(new Map(m.map((entry) => [entry.date, entry])))
    setLoading(false)
  }, [])

  useEffect(() => {
    reload().catch((err) => {
      console.error('Failed to load rhythm data', err)
      setLoading(false)
    })
  }, [reload])

  return { loading, habits, completions, moods, reload }
}

/** Derived per-habit streaks + today's completion state. */
export function useHabitStats(habits: Habit[], completions: Completion[], today: string = todayStr()) {
  return useMemo(() => {
    const byHabit = new Map<string, Set<string>>()
    for (const c of completions) {
      const set = byHabit.get(c.habitId) ?? new Set<string>()
      set.add(c.date)
      byHabit.set(c.habitId, set)
    }
    return new Map(
      habits.map((h) => {
        const dates = byHabit.get(h.id) ?? new Set<string>()
        return [
          h.id,
          {
            dates,
            doneToday: dates.has(today),
            current: currentStreak(dates, today),
            longest: longestStreak(dates)
          }
        ] as const
      })
    )
  }, [habits, completions, today])
}

