          </fieldset>

          <fieldset className="mt-5">
            <legend className="text-[11px] font-semibold uppercase tracking-[0.08em] text-[#787774] dark:text-[#A39E94] mb-2">
              Farbe
            </legend>
            <div className="flex items-center gap-2.5 flex-wrap">
              {HABIT_COLORS.map((c) => {
                const active = color === c.key
                return (
                  <button
                    key={c.key}
                    type="button"
                    onClick={() => setColor(c.key)}
                    aria-pressed={active}
                    aria-label={`Farbe ${c.label}`}
                    title={c.label}
                    className="w-11 h-11 inline-flex items-center justify-center rounded-full transition-transform active:scale-95"
                  >
                    <span
                      aria-hidden="true"
                      className={`block w-7 h-7 rounded-full transition-all ${
                        active ? 'ring-2 ring-offset-2 ring-offset-[#FFFFFF] dark:ring-offset-[#1E1D1B] ring-[#2F3437] dark:ring-[#EDEAE4] scale-110' : ''
                      }`}
                      style={{ backgroundColor: habitColor(c.key, resolvedTheme) }}
                    />
                  </button>
                )
              })}
            </div>
          </fieldset>

          <div className="flex items-center gap-3 mt-7">
            <button
              type="button"
              onClick={onClose}
              className="min-h-11 px-4 rounded-md text-[15px] font-semibold text-[#787774] dark:text-[#A39E94] hover:text-[#2F3437] dark:hover:text-[#EDEAE4] transition-colors"
            >
              Abbrechen
            </button>
            <button
              type="submit"
              disabled={!valid}
              className="flex-1 min-h-11 px-4 rounded-md bg-[#111111] dark:bg-[#EDEAE4] text-white dark:text-[#171614] text-[15px] font-semibold tracking-tight transition-all hover:bg-[#2A2A2A] dark:hover:bg-[#F4F2EE] active:scale-[0.98] disabled:opacity-40 disabled:pointer-events-none"
            >
              {initial ? 'Änderungen speichern' : 'Gewohnheit anlegen'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { MOODS, moodLabel } from '../lib/mood'
import type { MoodEntry } from '../types'

interface Props {
  mood: MoodEntry | undefined
  resolvedTheme: 'light' | 'dark'
  onSelect: (mood: 1 | 2 | 3 | 4 | 5) => void
  onSaveNote: (note: string) => void
  onClear: () => void
}

export default function MoodCard({ mood, resolvedTheme, onSelect, onSaveNote, onClear }: Props) {
  const [note, setNote] = useState(mood?.note ?? '')

  useEffect(() => {
    setNote(mood?.note ?? '')
  }, [mood?.note])

  const selected = mood?.mood ?? null

  return (
    <section aria-label="Stimmung" className="card p-5">
      <div className="flex items-baseline justify-between gap-3">
        <h2 className="text-[11px] font-semibold uppercase tracking-[0.12em] text-[#787774] dark:text-[#A39E94]">
          Stimmung heute
        </h2>
        {selected != null && (
          <span
            className="text-[11px] font-semibold uppercase tracking-[0.06em] px-2.5 py-1 rounded-full"
            style={{
              color: resolvedTheme === 'dark' ? '#E8A87C' : '#A8431F',
              backgroundColor: resolvedTheme === 'dark' ? 'rgba(232,168,124,0.14)' : '#FDF0E9'
            }}
          >
            {moodLabel(selected)}
          </span>
        )}
      </div>

      <div className="mt-4 grid grid-cols-5 gap-2" role="group" aria-label="Stimmung wählen">
        {MOODS.map((m) => {
          const active = selected === m.value
          return (
            <button
              key={m.value}
              type="button"
              onClick={() => onSelect(active ? (m.value as 1 | 2 | 3 | 4 | 5) : m.value)}
              aria-pressed={active}
              aria-label={`Stimmung ${m.value} von 5: ${m.label}`}
              title={m.label}
              className={`min-h-[52px] rounded-xl border text-[26px] leading-none inline-flex items-center justify-center transition-all duration-200 active:scale-95 ${
                active
                  ? 'border-[#A8431F] dark:border-[#E8A87C] bg-[#FDF0E9] dark:bg-[rgba(232,168,124,0.14)] scale-[1.03]'
                  : 'border-[#EAEAEA] dark:border-[#2A2926] bg-[#F9F9F8] dark:bg-[#262522] hover:border-[#D8D5CE] dark:hover:border-[#3A3835]'
              }`}
            >
              <span aria-hidden="true">{m.emoji}</span>
            </button>
          )
        })}
      </div>

      {selected != null && (
        <div className="mt-4 fade-in">
          <label htmlFor="mood-note" className="block text-[11px] font-semibold uppercase tracking-[0.08em] text-[#787774] dark:text-[#A39E94] mb-1.5">
            Kurznotiz <span className="normal-case tracking-normal font-normal">(optional)</span>
          </label>
          <div className="flex items-end gap-2">
            <textarea
              id="mood-note"
              value={note}
              rows={2}
              maxLength={140}
              placeholder="Wie geht es dir?"
              onChange={(e) => setNote(e.target.value)}
              onBlur={() => onSaveNote(note)}
              className="flex-1 resize-none rounded-lg border border-[#EAEAEA] dark:border-[#33322F] bg-[#F9F9F8] dark:bg-[#262522] px-3 py-2.5 text-[15px] text-[#2F3437] dark:text-[#EDEAE4] placeholder:text-[#B5B0A6] dark:placeholder:text-[#5B5852] focus:outline-none focus:border-[#A8431F] dark:focus:border-[#E8A87C] transition-colors"
            />
            <button
              type="button"
              onClick={() => onSaveNote(note)}
              className="min-h-11 px-4 rounded-md bg-[#111111] dark:bg-[#EDEAE4] text-white dark:text-[#171614] text-[14px] font-semibold tracking-tight transition-all hover:bg-[#2A2A2A] dark:hover:bg-[#F4F2EE] active:scale-[0.98]"
            >
              Speichern
            </button>
          </div>
          <button
            type="button"
            onClick={onClear}
            className="mt-2 text-[12px] font-medium text-[#787774] dark:text-[#A39E94] hover:text-[#A8431F] dark:hover:text-[#E8A87C] transition-colors min-h-8 px-1"
          >
            Stimmung entfernen
          </button>
        </div>
      )}
    </section>
  )
}

import { Flame, Trophy, Plus } from '@phosphor-icons/react'
import { formatLong, todayStr } from '../lib/dates'
import { habitColor, withAlpha } from '../lib/colors'
import type { Habit } from '../types'
import type { MoodEntry } from '../types'
import type { RhythmData } from '../hooks/useRhythmData'
import { useHabitStats } from '../hooks/useRhythmData'
import MoodCard from './MoodCard'
import EmptyState from './EmptyState'
import { Check } from '@phosphor-icons/react'

interface Props {
  data: RhythmData
  resolvedTheme: 'light' | 'dark'
  onToggleHabit: (id: string) => void
  onAddHabit: () => void
  onSelectMood: (value: 1 | 2 | 3 | 4 | 5) => void
  onSaveNote: (note: string) => void
  onClearMood: () => void
}

export default function TodayScreen({
  data,
  resolvedTheme,
  onToggleHabit,
  onAddHabit,
  onSelectMood,
  onSaveNote,
  onClearMood
}: Props) {
  const today = todayStr()
  const { habits, completions, moods, loading } = data
  const stats = useHabitStats(habits, completions, today)

  const total = habits.length
  const done = habits.filter((h) => stats.get(h.id)?.doneToday).length
  const progress = total > 0 ? done / total : 0

  return (
    <div className="px-5 pt-7 pb-6">
      {/* Header */}
      <header className="reveal" style={{ ['--index' as string]: 0 }}>
        <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-[#787774] dark:text-[#A39E94]">
          Heute
        </p>
        <h1 className="mt-1.5 font-serif text-[34px] leading-[1.08] tracking-[-0.02em] text-[#2F3437] dark:text-[#EDEAE4]">
          {formatLong(today)}
        </h1>

        {total > 0 && (
          <div className="mt-5 flex items-center justify-between gap-4">
            <p className="text-[14px] font-semibold tracking-tight text-[#2F3437] dark:text-[#EDEAE4]">
              {done} von {total} erledigt
            </p>
            <span className="text-[13px] font-medium tabular-nums text-[#787774] dark:text-[#A39E94]">
              {Math.round(progress * 100)} %
            </span>
          </div>
        )}
        {total > 0 && (
          <div
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={total}
            aria-valuenow={done}
            aria-label="Fortschritt heute"
            className="mt-2 h-1.5 rounded-full bg-[#EAEAEA] dark:bg-[#2A2926] overflow-hidden"
          >
            <div
              className="h-full rounded-full transition-[width] duration-500 ease-out"
              style={{
                width: `${progress * 100}%`,
                backgroundColor: resolvedTheme === 'dark' ? '#E8A87C' : '#A8431F'
              }}
            />
          </div>
        )}
      </header>

      {/* Habits */}
      <section aria-label="Gewohnheiten" className="mt-6">
        {loading ? (
          <div className="flex flex-col gap-3" aria-hidden="true">
            {[0, 1, 2].map((i) => (
              <div key={i} className="card h-[76px] animate-pulse" />
            ))}
          </div>
        ) : habits.length === 0 ? (
          <EmptyState
            icon={<Plus size={24} weight="bold" aria-hidden="true" />}
            title="Noch keine Gewohnheiten"
            body="Lege deine erste Gewohnheit an — zum Beispiel „Laufen“, „Lesen“ oder „Trinken“ — und baue daraus eine kleine tägliche Routine."
            action={{ label: 'Gewohnheit anlegen', onClick: onAddHabit }}
          />
        ) : (
          <ul className="flex flex-col gap-3">
            {habits.map((habit, i) => {
              const stat = stats.get(habit.id)!
              const color = habitColor(habit.color, resolvedTheme)
              const doneToday = stat.doneToday
              return (
                <li
                  key={habit.id}
                  className="reveal"
                  style={{ ['--index' as string]: i + 1 }}
                >
                  <button
                    type="button"
                    onClick={() => onToggleHabit(habit.id)}
                    aria-pressed={doneToday}
                    aria-label={`${habit.name}${doneToday ? ' erledigt' : ''} — Streak ${stat.current}`}
                    className="group w-full text-left card flex items-center gap-3.5 px-4 py-3.5 min-h-[76px] transition-all duration-200 active:scale-[0.985] hover:shadow-[0_1px_2px_rgba(23,22,20,0.04),0_14px_34px_rgba(23,22,20,0.06)]"
                    style={{
                      backgroundColor: doneToday
                        ? withAlpha(color, resolvedTheme === 'dark' ? 0.13 : 0.07)
                        : undefined
                    }}
                  >
                    <span
                      aria-hidden="true"
                      className={`shrink-0 w-8 h-8 rounded-full border-2 inline-flex items-center justify-center transition-all duration-200 ${
                        doneToday ? 'check-pop border-transparent' : 'border-[#D8D5CE] dark:border-[#3A3835] group-hover:border-[#B9B4AB] dark:group-hover:border-[#4A4742]'
                      }`}
                      style={doneToday ? { backgroundColor: color } : undefined}
                    >
                      {doneToday && (
                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                          <path
                            d="M5 13l4 4L19 7"
                            stroke={resolvedTheme === 'dark' ? '#171614' : '#FFFFFF'}
                            strokeWidth="3"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            className="draw-check"
                          />
                        </svg>
                      )}
                    </span>

                    <span
                      aria-hidden="true"
                      className="shrink-0 w-11 h-11 rounded-[10px] inline-flex items-center justify-center text-[24px] leading-none"
                      style={{
                        backgroundColor: withAlpha(color, resolvedTheme === 'dark' ? 0.16 : 0.11)
                      }}
                    >
                      {habit.emoji}
                    </span>

                    <span className="flex-1 min-w-0">
                      <span className="block truncate text-[16px] font-semibold tracking-tight text-[#2F3437] dark:text-[#EDEAE4]">
                        {habit.name}
                      </span>
                      <span className="mt-0.5 flex items-center gap-3 text-[12px] font-medium text-[#787774] dark:text-[#A39E94]">
                        <span className="inline-flex items-center gap-1">
                          <Flame size={12} weight="bold" aria-hidden="true" style={{ color: stat.current > 0 ? color : undefined }} />
                          {stat.current}
                        </span>
                        <span className="inline-flex items-center gap-1">
                          <Trophy size={12} weight="bold" aria-hidden="true" />
                          {stat.longest}
                        </span>
                      </span>
                    </span>

                    <span className="shrink-0 text-right">
                      {doneToday ? (
                        <span
                          className="inline-flex items-center gap-1 text-[11px] font-semibold uppercase tracking-[0.06em] px-2.5 py-1 rounded-full"
                          style={{
                            color,
                            backgroundColor: withAlpha(color, resolvedTheme === 'dark' ? 0.16 : 0.1)
                          }}
                        >
                          <Check size={12} weight="bold" aria-hidden="true" />
                          Erledigt
                        </span>
                      ) : (
                        <span className="text-[12px] font-medium text-[#A39E94] dark:text-[#5B5852]">
                          offen
                        </span>
                      )}
                    </span>
                  </button>
                </li>
              )
            })}
          </ul>
        )}
      </section>

      {/* Mood */}
      <div className="mt-6 reveal" style={{ ['--index' as string]: 4 }}>
        <MoodCard
          mood={moods.get(today)}
          resolvedTheme={resolvedTheme}
          onSelect={onSelectMood}
          onSaveNote={onSaveNote}
          onClear={onClearMood}
        />
      </div>
    </div>
  )
}

import { useMemo } from 'react'
import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip
} from 'recharts'
import { CalendarBlank } from '@phosphor-icons/react'
import { lastNDays, todayStr, weekdayShort, dayMonthShort } from '../lib/dates'
import { moodDef } from '../lib/mood'
import type { RhythmData } from '../hooks/useRhythmData'
import EmptyState from './EmptyState'

interface Props {
  data: RhythmData
  resolvedTheme: 'light' | 'dark'
  onAddHabit: () => void
}

interface ChartDay {
  date: string
  label: string
  done: number
  total: number
  mood: number | null
  moodLabel: string
}

const ACCENT_LIGHT = '#A8431F'
const ACCENT_DARK = '#E8A87C'
const MOOD_LIGHT = '#B57718'
const MOOD_DARK = '#D8B65C'

export default function WeekScreen({ data, resolvedTheme, onAddHabit }: Props) {
  const { habits, completions, moods, loading } = data
  const today = todayStr()

  const accent = resolvedTheme === 'dark' ? ACCENT_DARK : ACCENT_LIGHT
  const moodColor = resolvedTheme === 'dark' ? MOOD_DARK : MOOD_LIGHT
  const gridColor = resolvedTheme === 'dark' ? 'rgba(255,255,255,0.07)' : '#EAEAEA'
  const textColor = resolvedTheme === 'dark' ? '#A39E94' : '#787774'

  const days = useMemo<ChartDay[]>(() => {
    const dates = lastNDays(7, today)
    const doneByDate = new Map<string, number>()
    for (const c of completions) {
      if (dates.includes(c.date)) {
        doneByDate.set(c.date, (doneByDate.get(c.date) ?? 0) + 1)
      }
    }
    return dates.map((date) => {
      const entry = moods.get(date)
      const def = entry ? moodDef(entry.mood) : undefined
      return {
        date,
        label: weekdayShort(date),
        done: doneByDate.get(date) ?? 0,
        total: habits.length,
        mood: entry ? entry.mood : null,
        moodLabel: def?.label ?? ''
      }
    })
  }, [completions, moods, habits, today])

  const totalDays = days.length
  const totalHabits = habits.length
  const hasData = days.some((d) => d.done > 0 || d.mood != null)

  const moodValues = days.filter((d) => d.mood != null).map((d) => d.mood as number)
  const avgMood = moodValues.length
    ? moodValues.reduce((a, b) => a + b, 0) / moodValues.length
    : null

  const progresses = days
    .filter((d) => d.total > 0)
    .map((d) => d.done / d.total)
  const avgProgress = progresses.length
    ? progresses.reduce((a, b) => a + b, 0) / progresses.length
    : null

  const maxDone = Math.max(1, ...days.map((d) => d.done))

  return (
    <div className="px-5 pt-7 pb-6">
      <header className="reveal" style={{ ['--index' as string]: 0 }}>
        <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-[#787774] dark:text-[#A39E94]">
          Woche
        </p>
        <h1 className="mt-1.5 font-serif text-[34px] leading-[1.08] tracking-[-0.02em] text-[#2F3437] dark:text-[#EDEAE4]">
          Letzte 7 Tage
        </h1>
      </header>

      {!loading && !hasData && (
        <div className="mt-6">
          <EmptyState
            icon={<CalendarBlank size={24} weight="bold" aria-hidden="true" />}
            title="Noch keine Daten"
            body={totalHabits === 0
              ? 'Lege deine Gewohnheiten an und haken sie ab — hier wachsen mit der Zeit Fortschritt und Stimmungsverlauf.'
              : 'Heute ist der Startschuss. Habe die Woche deine Gewohnheiten ab und zeichne deine Stimmung — dann zeigt diese Ansicht den Verlauf.'}
            action={totalHabits === 0 ? { label: 'Gewohnheit anlegen', onClick: onAddHabit } : undefined}
          />
        </div>
      )}

      {hasData && (
        <>
          {/* Summary chips */}
          <div className="mt-5 grid grid-cols-2 gap-3 reveal" style={{ ['--index' as string]: 1 }}>
            <div className="card px-4 py-3.5">
              <p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-[#787774] dark:text-[#A39E94]">
                Ø Stimmung
              </p>
              <p className="mt-1 font-serif text-[24px] leading-none tracking-tight text-[#2F3437] dark:text-[#EDEAE4] tabular-nums">
                {avgMood != null ? avgMood.toFixed(1) : '—'}
              </p>
              <p className="mt-1 text-[11px] text-[#787774] dark:text-[#A39E94]">
                {moodValues.length > 0 ? `${moodValues.length} von ${totalDays} Tagen` : 'keine Werte'}
              </p>
            </div>
            <div className="card px-4 py-3.5">
              <p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-[#787774] dark:text-[#A39E94]">
                Ø Fortschritt
              </p>
              <p className="mt-1 font-serif text-[24px] leading-none tracking-tight text-[#2F3437] dark:text-[#EDEAE4] tabular-nums">
                {avgProgress != null ? `${Math.round(avgProgress * 100)} %` : '—'}
              </p>
              <p className="mt-1 text-[11px] text-[#787774] dark:text-[#A39E94]">
                {totalHabits > 0 ? `${totalHabits} Gewohnheiten` : 'keine Gewohnheiten'}
              </p>
            </div>
          </div>

          {/* Chart */}
          <div className="mt-4 card p-4 reveal" style={{ ['--index' as string]: 2 }}>
            <p className="px-1 text-[11px] font-semibold uppercase tracking-[0.12em] text-[#787774] dark:text-[#A39E94]">
              Fortschritt & Stimmung
            </p>
            <div className="mt-3 h-[220px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={days} margin={{ top: 8, right: 0, bottom: 0, left: -22 }}>
                  <CartesianGrid stroke={gridColor} strokeDasharray="3 6" vertical={false} />
                  <XAxis
                    dataKey="label"
                    tick={{ fill: textColor, fontSize: 11, fontWeight: 600 }}
                    axisLine={false}
                    tickLine={false}
                    dy={6}
                  />
                  <YAxis
                    yAxisId="habits"
                    domain={[0, Math.max(1, totalHabits)]}
                    tick={{ fill: textColor, fontSize: 10 }}
                    axisLine={false}
                    tickLine={false}
                    ticks={totalHabits > 0 ? Array.from({ length: totalHabits + 1 }, (_, i) => i) : [0, 1]}
                    allowDecimals={false}
                  />
                  <YAxis
                    yAxisId="mood"
                    orientation="right"
                    domain={[1, 5]}
                    tick={{ fill: textColor, fontSize: 10 }}
                    axisLine={false}
                    tickLine={false}
                    ticks={[1, 2, 3, 4, 5]}
                    allowDecimals={false}
                  />
                  <Tooltip
                    content={({ active, payload }) => {
                      if (!active || !payload || payload.length === 0) return null
                      const d = payload[0]?.payload as ChartDay
                      return (
                        <div className="rounded-lg border border-[#EAEAEA] dark:border-[#33322F] bg-[#FFFFFF] dark:bg-[#262522] px-3 py-2 shadow-[0_4px_16px_rgba(0,0,0,0.08)]">
                          <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-[#787774] dark:text-[#A39E94]">
                            {dayMonthShort(d.date)}
                          </p>
                          <p className="mt-1 text-[13px] font-semibold text-[#2F3437] dark:text-[#EDEAE4]">
                            {d.total > 0 ? `${d.done} von ${d.total} erledigt` : 'keine Gewohnheiten'}
                          </p>
                          {d.mood != null ? (
                            <p className="text-[13px] text-[#787774] dark:text-[#A39E94]">
                              Stimmung {d.mood} — {d.moodLabel}
                            </p>
                          ) : (
                            <p className="text-[13px] text-[#787774] dark:text-[#A39E94]">keine Stimmung</p>
                          )}
                        </div>
                      )
                    }}
                  />
                  <Bar
                    yAxisId="habits"
                    dataKey="done"
                    fill={accent}
                    radius={[5, 5, 0, 0]}
                    maxBarSize={26}
                  />
                  <Line
                    yAxisId="mood"
                    type="monotone"
                    dataKey="mood"
                    stroke={moodColor}
                    strokeWidth={2.5}
                    dot={{ r: 3.5, fill: moodColor, strokeWidth: 0 }}
                    activeDot={{ r: 5, fill: moodColor, strokeWidth: 2, stroke: resolvedTheme === 'dark' ? '#171614' : '#FFFFFF' }}
                    connectNulls
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-3 flex items-center justify-center gap-5">
              <span className="inline-flex items-center gap-1.5 text-[11px] font-medium text-[#787774] dark:text-[#A39E94]">
                <span aria-hidden="true" className="w-3 h-3 rounded-[3px]" style={{ backgroundColor: accent }} />
                Erledigt
              </span>
              <span className="inline-flex items-center gap-1.5 text-[11px] font-medium text-[#787774] dark:text-[#A39E94]">
                <span aria-hidden="true" className="w-3 h-[3px] rounded-full" style={{ backgroundColor: moodColor }} />
                Stimmung
              </span>
            </div>
          </div>

          {/* Day list */}
          <ul className="mt-4 flex flex-col gap-2 reveal" style={{ ['--index' as string]: 3 }}>
            {[...days].reverse().map((d) => (
              <li key={d.date} className="card px-4 py-3 flex items-center gap-3">
                <span className="w-14 text-[13px] font-semibold text-[#2F3437] dark:text-[#EDEAE4] tabular-nums">
                  {weekdayShort(d.date)}
                </span>
                <span className="text-[11px] text-[#787774] dark:text-[#A39E94] tabular-nums w-10">
                  {dayMonthShort(d.date)}
                </span>
                <span className="flex-1 h-1.5 rounded-full bg-[#EAEAEA] dark:bg-[#2A2926] overflow-hidden">
                  <span
